if (!args.url || typeof args.url !== 'string') {
  throw new Error("El parámetro 'url' es requerido.");
}
const raw = args.url.trim();
let videoId = null;

if (/^[a-zA-Z0-9_-]{11}$/.test(raw)) {
  videoId = raw;
} else if (raw.includes('youtu.be/')) {
  const m = raw.match(/youtu\.be\/([a-zA-Z0-9_-]{11})/);
  if (m) videoId = m[1];
} else if (raw.includes('/shorts/')) {
  const m = raw.match(/\/shorts\/([a-zA-Z0-9_-]{11})/);
  if (m) videoId = m[1];
} else if (raw.includes('/embed/')) {
  const m = raw.match(/\/embed\/([a-zA-Z0-9_-]{11})/);
  if (m) videoId = m[1];
} else {
  const m = raw.match(/[?&]v=([a-zA-Z0-9_-]{11})/);
  if (m) videoId = m[1];
}

if (!videoId || videoId.length !== 11) {
  throw new Error("No se encontró un ID de video de YouTube válido (debe tener 11 caracteres).");
}

return {
  video_id: videoId
};

if (!args.video_id || typeof args.video_id !== 'string') {
  throw new Error("El parámetro 'video_id' es requerido.");
}
const vId = args.video_id.trim();
const videoUrl = 'https://www.youtube.com/watch?v=' + encodeURIComponent(vId);
const oembedUrl = 'https://www.youtube.com/oembed?url=' + encodeURIComponent(videoUrl) + '&format=json';

const res = await ctx.fetch(oembedUrl);
if (!res.ok) {
  return {
    encontrado: false,
    video_id: vId,
    titulo: null,
    autor: null,
    autor_url: null,
    miniatura_url: null
  };
}

const data = typeof res.json === 'function' ? await res.json() : (typeof res.json === 'object' && res.json !== null ? res.json : JSON.parse(res.text || '{}'));

return {
  encontrado: true,
  video_id: vId,
  titulo: data.title || null,
  autor: data.author_name || null,
  autor_url: data.author_url || null,
  miniatura_url: data.thumbnail_url || `https://i.ytimg.com/vi/${vId}/hqdefault.jpg`
};

if (!args.video_id || typeof args.video_id !== 'string') {
  throw new Error("El parámetro 'video_id' es requerido.");
}
const vId = args.video_id.trim();
const pageUrl = `https://www.youtube.com/watch?v=${encodeURIComponent(vId)}`;

const res = await ctx.fetch(pageUrl, {
  headers: {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/115.0.0.0 Safari/537.36',
    'Accept-Language': 'es-ES,es;q=0.9,en;q=0.8'
  }
});

if (!res.ok) {
  return {
    disponible: false,
    motivo: `Respuesta HTTP ${res.status} al consultar el video`,
    transcripcion: null
  };
}

const html = res.text || '';
const match = html.match(/"captionTracks":\s*(\[.*?\])/);
if (!match) {
  return {
    disponible: false,
    motivo: 'El video no tiene pistas de subtítulos/transcripción públicas accesibles directamente o YouTube requiere autenticación.',
    transcripcion: null
  };
}

let captionTracks = [];
try {
  captionTracks = JSON.parse(match[1]);
} catch (e) {
  return {
    disponible: false,
    motivo: 'Error al parsear las pistas de subtítulos',
    transcripcion: null
  };
}

if (!captionTracks.length) {
  return {
    disponible: false,
    motivo: 'No se encontraron pistas de subtítulos.',
    transcripcion: null
  };
}

// Preferir español si existe, si no la primera pista
const track = captionTracks.find(t => (t.languageCode || '').startsWith('es')) || captionTracks[0];
const subUrl = track.baseUrl + '&fmt=json3';

const subRes = await ctx.fetch(subUrl);
if (!subRes.ok) {
  // Intentar sin json3 (XML)
  const xmlRes = await ctx.fetch(track.baseUrl);
  if (!xmlRes.ok) {
    return {
      disponible: false,
      idioma: track.languageCode,
      motivo: 'No se pudo descargar el contenido de los subtítulos.',
      transcripcion: null
    };
  }
  const xmlText = xmlRes.text || '';
  const clean = xmlText
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();

  return {
    disponible: true,
    idioma: track.languageCode,
    texto_completo: clean.slice(0, 15000),
    caracteres: clean.length,
    truncado: clean.length > 15000
  };
}

const subData = typeof subRes.json === 'function' ? await subRes.json() : (typeof subRes.json === 'object' && subRes.json !== null ? subRes.json : JSON.parse(subRes.text || '{}'));

const fragments = [];
if (Array.isArray(subData.events)) {
  for (const ev of subData.events) {
    if (Array.isArray(ev.segs)) {
      const segText = ev.segs.map(s => s.utf8 || '').join('').trim();
      if (segText) fragments.push(segText);
    }
  }
}

const texto = fragments.join(' ');
return {
  disponible: true,
  idioma: track.languageCode,
  texto_completo: texto.slice(0, 15000),
  caracteres: texto.length,
  truncado: texto.length > 15000
};

if (typeof args.vistas !== 'number' || args.vistas <= 0) {
  throw new Error("El parámetro 'vistas' debe ser un número mayor a 0.");
}
if (typeof args.likes !== 'number' || args.likes < 0) {
  throw new Error("El parámetro 'likes' debe ser un número mayor o igual a 0.");
}
if (typeof args.comentarios !== 'number' || args.comentarios < 0) {
  throw new Error("El parámetro 'comentarios' debe ser un número mayor o igual a 0.");
}
const rate = Math.round(((args.likes + args.comentarios) / args.vistas) * 10000) / 100;
return {
  engagement_rate_pct: rate
};

if (!args.duracion_iso || typeof args.duracion_iso !== 'string') {
  throw new Error("El parámetro 'duracion_iso' es requerido.");
}
const m = args.duracion_iso.trim().match(/^PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/i);
if (!m) {
  throw new Error("Formato ISO 8601 no válido. Ejemplo esperado: 'PT1H15M30S' o 'PT4M20S'.");
}
const h = parseInt(m[1] || '0', 10);
const min = parseInt(m[2] || '0', 10);
const s = parseInt(m[3] || '0', 10);
const total = h * 3600 + min * 60 + s;
return {
  segundos: total
};

if (typeof args.segundos !== 'number' || !Number.isFinite(args.segundos) || args.segundos < 0) {
  throw new Error("El parámetro 'segundos' debe ser un número finito no negativo.");
}
const secTotal = Math.round(args.segundos);
const h = Math.floor(secTotal / 3600);
const m = Math.floor((secTotal % 3600) / 60);
const s = secTotal % 60;
const pad = (n) => String(n).padStart(2, '0');
const tiempo = h > 0 ? `${pad(h)}:${pad(m)}:${pad(s)}` : `${pad(m)}:${pad(s)}`;
return {
  tiempo_legible: tiempo
};
